INSERT INTO standards
(is_number, standard_title, applicability, required_documents, procedures, official_source, testing_certification, last_verified)
VALUES
('IS 1417:2016', 'Gold and gold alloys, jewellery/artefacts — Fineness and marking — Specification (Fourth Revision)', 'Gold and gold-alloy jewellery/artefacts; the standard also covers gold bullion and coins. BIS states that the standard permits gold jewellery/artefacts at 14K(585), 18K(750), 20K(833), 22K(916), 23K(958) and 24KS(995).', 'Not specified as an application-document checklist in the standard itself. For hallmarking, BIS-registered/certified jewellers submit articles to a BIS-recognized Assaying & Hallmarking Centre (AHC).', 'The jeweller submits jewellery/artefacts to a BIS-recognized AHC for examination/assaying. Articles conforming to the applicable requirements are hallmarked. Since HUID was introduced for gold hallmarking, the current hallmark consists of the BIS logo, purity in caratage/fineness, and a six-digit alphanumeric HUID.', 'https://www.bis.gov.in/qazwsx/hmd/Implementation_IS_1417_14122016.pdf ; https://www.bis.gov.in/hallmarking-overview/hallmarking-faqs/hallmarking-faq/?lang=en', 'Fineness/gold-content testing is required. BIS-recognized AHCs perform the applicable assaying; BIS also states that purity can be tested by the fire-assay method as per IS 1418. BIS LIMS lists testing under IS 1417 for fineness/gold content and related impurity checks.', '2026-08-28');
INSERT INTO standards
(is_number, standard_title, applicability, required_documents, procedures, official_source, testing_certification, last_verified)
VALUES
('IS 2112:2025', 'Silver and silver alloys, jewellery and articles — Fineness and marking — Specification (revised standard)', 'Silver jewellery and articles covered by the revised silver hallmarking standard. BIS reported that IS 2112:2025 replaced IS 2112:2014 and introduced HUID-based silver hallmarking on a voluntary basis from 1 September 2025.', 'Not specified as an application-document checklist in the standard record used here. For hallmarking, BIS-registered/certified jewellers submit silver articles to a BIS-recognized AHC.', 'Registered jeweller submits silver articles to a BIS-recognized AHC. The hallmarking workflow includes request for hallmarking, examination/sampling, assaying and hallmarking for conforming articles; failed articles are rejected/returned to the jeweller. The revised standard introduced HUID-based silver hallmarking.', 'https://www.bis.gov.in/wp-content/uploads/2025/10/BIS-NEWSLETTER-OCTOBER-2025.pdf', 'Silver fineness is assayed under the applicable BIS requirements. BIS identifies IS 2113 as the standard for assaying silver in silver and silver alloys; the methods include gravimetric and volumetric (potentiometric) methods. BIS LIMS also lists fineness testing for IS 2112.', '2026-08-28');
INSERT INTO standards
(is_number, standard_title, applicability, required_documents, procedures, official_source, testing_certification, last_verified)
VALUES
('IS 15820:2024', 'Establishment and operation of Assaying and Hallmarking Centres — General Requirements (First Revision)', 'Assaying and Hallmarking Centres (AHCs) that assay and hallmark gold/silver jewellery and artefacts. IS 15820:2024 revised and replaced IS 15820:2009; BIS aligned the revised standard with IS/ISO/IEC 17025:2017 requirements.', 'For recognition, BIS states that an AHC applies on the prescribed application form and submits a Quality Manual developed on the basis of the Generic Quality Manual. BIS also provides application/affidavit/renewal forms for AHC recognition.', 'Set up the AHC according to the applicable requirements; apply online through the BIS portal using the prescribed application; submit the required quality documentation; BIS assesses the centre''s infrastructure, quality-management system and competent manpower before recognition. Recognized AHCs operate and are surveilled according to the applicable BIS requirements.', 'https://www.bis.gov.in/wp-content/uploads/2024/10/Implementation-Guidelines-IS-15820.pdf ; https://www.bis.gov.in/hallmarking-overview/?lang=en', 'The AHC must have the infrastructure, quality-management system and competent manpower needed for assaying/hallmarking. The revised standard includes requirements relating to impartiality, confidentiality, competence, CCTV recording, measurement uncertainty and proficiency testing; BIS states that AHCs are recognized after verification of the required infrastructure and quality system.', '2026-08-28');
INSERT INTO standards
(is_number, standard_title, applicability, required_documents, procedures, official_source, testing_certification, last_verified)
VALUES
('IS 1418:2009', 'Determination of gold in gold bullion, gold alloys and gold jewellery/artefacts — Cupellation (Fire Assay) Method', 'Determination of gold content in gold bullion, gold alloys and gold jewellery/artefacts.', 'Not an application/registration standard; it specifies a test method. No separate application-document checklist is recorded for this standard.', 'Samples are tested using the cupellation (fire assay) method for determination of gold content. BIS states that a common person can have hallmarked jewellery tested at a recognized AHC using the fire-assay method as per IS 1418, subject to the applicable testing charge.', 'https://www.bis.gov.in/hallmarking-overview/hallmarking-faqs/hallmarking-faq/?lang=en', 'Fire assay/cupellation is the specified testing method. BIS uses IS 1418 for testing gold content and states that recognized AHCs can test hallmarked jewellery for purity using this method.', '2026-08-28');
INSERT INTO standards
(is_number, standard_title, applicability, required_documents, procedures, official_source, testing_certification, last_verified)
VALUES
('IS 2113:2014', 'Assaying silver in silver and silver alloys — Methods (Third Revision)', 'Determination/assaying of silver in silver and silver-alloy materials, including applications connected with silver hallmarking.', 'Not an application/registration standard; it specifies assaying methods. No separate application-document checklist is recorded for this standard.', 'Silver samples are assayed using the methods specified by the standard. BIS''s 2025 hallmarking material identifies gravimetric and volumetric (potentiometric) methods for determination of silver in silver alloys.', 'https://www.bis.gov.in/hallmarking-overview/hallmarking-faqs/hallmarking-faq/?lang=en ; https://www.bis.gov.in/wp-content/uploads/2025/10/BIS-NEWSLETTER-OCTOBER-2025.pdf', 'BIS identifies gravimetric and volumetric (potentiometric) methods for determination of silver in silver alloys. The standard is the testing-method reference supporting silver assaying.', '2026-08-28');
